import React, { useState, useEffect, useRef } from 'react';

const MapView = ({ properties, focusId }) => {
  const mapRef = useRef(null);
  const [map, setMap] = useState(null);
  const [markers, setMarkers] = useState([]);

  // استبدل هذا المفتاح بمفتاح API الخاص بك من Google Cloud Console
  const API_KEY = 'YOUR_GOOGLE_MAPS_API_KEY';

  useEffect(() => {
    const initMap = () => {
      if (!mapRef.current) return;

      const defaultLocation = { lat: 30.0444, lng: 31.2357 }; // القاهرة
      const mapInstance = new window.google.maps.Map(mapRef.current, {
        center: defaultLocation,
        zoom: 10,
        styles: [
            {
                "featureType": "poi",
                "elementType": "labels",
                "stylers": [{ "visibility": "off" }]
            }
        ]
      });

      setMap(mapInstance);
    };

    if (!window.google) {
      const script = document.createElement('script');
      script.src = `https://maps.googleapis.com/maps/api/js?key=${API_KEY}&libraries=places&language=ar`;
      script.async = true;
      script.defer = true;
      script.onload = initMap;
      document.body.appendChild(script);
    } else {
      initMap();
    }
  }, []);

  useEffect(() => {
    if (map && properties) {
      // Clear old markers
      markers.forEach(m => m.setMap(null));
      const newMarkers = [];

      const infoWindow = new window.google.maps.InfoWindow();

      properties.forEach(prop => {
        if (prop.location?.lat && prop.location?.lng) {
            const position = { lat: Number(prop.location.lat), lng: Number(prop.location.lng) };
            const marker = new window.google.maps.Marker({
                position: position,
                map: map,
                title: prop.type,
                animation: window.google.maps.Animation.DROP
            });

            marker.addListener("click", () => {
                const content = `
                    <div style="text-align:right; direction:rtl; min-width: 200px;">
                        <h6 style="margin-bottom:5px;">${prop.type} ${prop.status}</h6>
                        <p style="margin-bottom:5px; font-size:12px; color:#666;">${prop.location.city}</p>
                        <img src="${prop.imageUrl}" style="width:100%; height:100px; object-fit:cover; border-radius:4px; margin-bottom:5px;">
                        <div style="font-weight:bold; color:#198754;">${prop.price?.toLocaleString()} ج</div>
                    </div>
                `;
                infoWindow.setContent(content);
                infoWindow.open(map, marker);
            });
            newMarkers.push(marker);
        }
      });
      setMarkers(newMarkers);
    }
  }, [map, properties]);

  useEffect(() => {
    if (map && focusId && properties) {
        const prop = properties.find(p => p.id === focusId);
        if (prop && prop.location?.lat && prop.location?.lng) {
            const pos = { lat: Number(prop.location.lat), lng: Number(prop.location.lng) };
            map.panTo(pos);
            map.setZoom(15);
        }
    }
  }, [map, focusId, properties]);

  return (
    <div className="map-container shadow-lg" style={{ height: 'calc(100vh - 200px)', minHeight: '500px', position: 'relative', borderRadius: '15px', overflow: 'hidden' }}>
      <div ref={mapRef} style={{ width: '100%', height: '100%' }} />
      {API_KEY === 'YOUR_GOOGLE_MAPS_API_KEY' && !window.google && (
          <div style={{position:'absolute', top:0, left:0, width:'100%', height:'100%', background:'rgba(0,0,0,0.7)', color:'white', display:'flex', alignItems:'center', justifyContent:'center', zIndex:1000}}>
              <div className="text-center p-4">
                  <h3>⚠️ تنبيه</h3>
                  <p>لم يتم تفعيل خرائط جوجل.</p>
                  <p>يرجى استبدال <code>YOUR_GOOGLE_MAPS_API_KEY</code> في الكود بمفتاح API صالح.</p>
              </div>
          </div>
      )}
    </div>
  );
};

export default MapView;
